<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import L from 'leaflet'
const emit=defineEmits(['close'])
const mapEl=ref(null),data=ref({revision:0,stops:[],routes:[],vehicles:[]}),baseline=ref(''),error=ref(''),message=ref(''),action=ref(''),selectedRoute=ref(''),selectedStop=ref(''),stopName=ref(''),vehicleName=ref(''),vehicleCapacity=ref(30),cameraId=ref(''),testCounts=ref({}),busy=ref(false)
const route=computed(()=>data.value.routes.find(r=>r.id===selectedRoute.value)),stop=computed(()=>data.value.stops.find(s=>s.id===selectedStop.value))
const dirty=computed(()=>JSON.stringify(data.value)!==baseline.value)
let map,layer,observer
async function api(path='',body,method='PUT'){const r=await fetch('/api/transit'+path,body?{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d}
async function load(){try{data.value=await api();baseline.value=JSON.stringify(data.value);if(!data.value.routes.some(r=>r.id===selectedRoute.value))selectedRoute.value=data.value.routes[0]?.id||'';paint()}catch(e){error.value=e.message}}
function paint(){if(!layer)return;layer.clearLayers();for(const r of data.value.routes){const text=document.createElement('span');text.textContent=r.name;L.polyline(r.points.map(p=>[p.latitude,p.longitude]),{color:r.color,weight:r.id===selectedRoute.value?6:3}).bindTooltip(text).on('click',()=>{selectedRoute.value=r.id;action.value='';paint()}).addTo(layer);if(r.id===selectedRoute.value)r.points.forEach(p=>L.circleMarker([p.latitude,p.longitude],{radius:3,color:r.color}).addTo(layer))}for(const s of data.value.stops){const text=document.createElement('span');text.textContent=s.name;L.circleMarker([s.latitude,s.longitude],{radius:s.id===selectedStop.value?9:6,color:'#7c3aed',fillColor:'white',fillOpacity:1}).bindTooltip(text,{permanent:true,direction:'top'}).on('click',e=>{L.DomEvent.stopPropagation(e);selectedStop.value=s.id;action.value='';paint()}).addTo(layer)}}
function addRoute(){const id=crypto.randomUUID();data.value.routes.push({id,name:'新公交线路',color:'#8b5cf6',points:[],stop_ids:[]});selectedRoute.value=id;action.value='route';paint()}
function removeRoute(){data.value.vehicles=data.value.vehicles.filter(v=>v.route_id!==selectedRoute.value);data.value.routes=data.value.routes.filter(r=>r.id!==selectedRoute.value);selectedRoute.value='';action.value='';paint()}
function removeStop(){for(const r of data.value.routes)r.stop_ids=r.stop_ids.filter(id=>id!==selectedStop.value);data.value.stops=data.value.stops.filter(s=>s.id!==selectedStop.value);selectedStop.value='';paint()}
function reorder(index,delta){const ids=route.value.stop_ids,j=index+delta;if(j<0||j>=ids.length)return;[ids[index],ids[j]]=[ids[j],ids[index]]}
function addVehicle(){if(!route.value||!vehicleName.value.trim())return;data.value.vehicles.push({id:crypto.randomUUID(),name:vehicleName.value.trim(),route_id:route.value.id,capacity:vehicleCapacity.value,camera_id:cameraId.value,observation:null});vehicleName.value='';cameraId.value=''}
async function save(){busy.value=true;error.value='';try{data.value=await api('',data.value);baseline.value=JSON.stringify(data.value);message.value='公交线路、站点、车辆已保存';paint()}catch(e){error.value=e.message}finally{busy.value=false}}
async function observe(v){if(dirty.value){error.value='先保存线路和车辆配置，再提交人数';return}busy.value=true;error.value='';try{await api('/vehicles/'+v.id+'/observations',{count:Number(testCounts.value[v.id]??0),captured_at:new Date().toISOString(),source:'manual_test'},'POST');await load();message.value='测试人数已更新到应用公交图层'}catch(e){error.value=e.message}finally{busy.value=false}}
function exportJson(){const url=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='campusflow-transit.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function close(){if(!dirty.value||confirm('公交数据未保存，是否离开？'))emit('close')}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{await nextTick();map=L.map(mapEl.value,{zoomControl:false});L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);layer=L.featureGroup().addTo(map);map.on('click',e=>{const p={longitude:e.latlng.lng,latitude:e.latlng.lat};if(action.value==='route'&&route.value)route.value.points.push(p);if(action.value==='stop'&&stopName.value.trim()){const s={id:crypto.randomUUID(),name:stopName.value.trim(),...p};data.value.stops.push(s);selectedStop.value=s.id;stopName.value='';action.value=''}if(action.value==='move'&&stop.value){Object.assign(stop.value,p);action.value=''}paint()});observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(mapEl.value);await load();try{const r=await fetch('/api/navigation/map');const d=await r.json();const road=L.geoJSON(d,{style:{color:'#d5b44e',weight:2,opacity:.5}}).addTo(map);if(road.getBounds().isValid())map.fitBounds(road.getBounds(),{padding:[20,20]})}catch{if(layer.getBounds().isValid())map.fitBounds(layer.getBounds())}window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{observer?.disconnect();map?.remove();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><Teleport to="body"><section class="transit-workbench" aria-label="公交线路与站点工作台"><header><strong>公交线路、站点与车内拥挤度</strong><span>{{dirty?'有未保存修改':'已保存'}} · 版本 {{data.revision}}</span><button :disabled="busy" @click="save">保存全部</button><button @click="exportJson">导出JSON</button><button @click="close">返回</button></header>
 <div class="layout"><aside><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><p>先绘制线路，再添加站点并按行车顺序排列。绘制内容由你提供，不自动生成校园公交数据。</p>
  <h3>1. 线路</h3><select v-model="selectedRoute" @change="action='';paint()"><option value="">选择线路</option><option v-for="r in data.routes" :key="r.id" :value="r.id">{{r.name}}</option></select><button @click="addRoute">新增线路</button>
  <template v-if="route"><label>线路名称<input v-model="route.name" maxlength="100" @input="paint"></label><label>线路颜色<input v-model="route.color" type="color" @input="paint"></label><p>已绘制 {{route.points.length}} 个折线点，按行车方向依次点击；往返线可分别建立。</p><button :class="{active:action==='route'}" @click="action=action==='route'?'':'route'">{{action==='route'?'结束绘制':'继续画线'}}</button><button @click="route.points.pop();paint()">撤销一点</button><button @click="removeRoute">删除本线及所属车辆</button></template>
  <h3>2. 停站点</h3><label>新站名<input v-model="stopName" maxlength="100" placeholder="填写站名，再点地图"></label><button :class="{active:action==='stop'}" :disabled="!stopName.trim()" @click="action='stop'">在地图添加站点</button><select v-model="selectedStop" @change="paint"><option value="">选择站点</option><option v-for="s in data.stops" :key="s.id" :value="s.id">{{s.name}}</option></select><template v-if="stop"><input v-model="stop.name" maxlength="100" @input="paint"><button @click="action='move'">点击地图移动此站</button><button @click="removeStop">删除此站</button></template>
  <template v-if="route"><h4>本线停站（勾选后可调整顺序）</h4><label v-for="s in data.stops" :key="s.id" class="check"><input type="checkbox" v-model="route.stop_ids" :value="s.id">{{s.name}}</label><div v-for="(id,i) in route.stop_ids" :key="id" class="stop-order">{{i+1}}. {{data.stops.find(s=>s.id===id)?.name}}<button @click="reorder(i,-1)">↑</button><button @click="reorder(i,1)">↓</button></div></template>
  <h3>3. 车辆与摄像头</h3><p>先选择所属线路。车内总人数÷车辆总容量＝拥挤度，可超过100%。摄像头ID用于后续识别程序上报，不会自动连接视频流。</p><label>车辆名称<input v-model="vehicleName" maxlength="100"></label><label>人员总容量<input v-model.number="vehicleCapacity" type="number" min="1" max="1000"></label><label>摄像头ID<input v-model="cameraId" maxlength="100" placeholder="如 bus-01-interior"></label><button :disabled="!route||!vehicleName.trim()" @click="addVehicle">添加到所选线路</button>
  <section v-for="v in data.vehicles" :key="v.id" class="vehicle"><label>车辆名称<input v-model="v.name" maxlength="100"></label><label>总容量<input v-model.number="v.capacity" type="number" min="1" max="1000"></label><label>摄像头ID<input v-model="v.camera_id" maxlength="100"></label><small>车辆ID：{{v.id}}</small><p>{{data.routes.find(r=>r.id===v.route_id)?.name}}</p><p v-if="v.observation">{{v.observation.count}} 人 · {{v.observation.percent}}% · {{v.observation.source==='camera'?'摄像头数据':'手动测试'}}<br>{{new Date(v.observation.captured_at).toLocaleString()}}</p><label>测试车内人数<input v-model.number="testCounts[v.id]" type="number" min="0" max="10000"></label><button :disabled="busy" @click="observe(v)">提交测试人数</button><button @click="data.vehicles=data.vehicles.filter(x=>x.id!==v.id)">删除车辆</button></section>
  <button :disabled="busy" @click="save">保存全部</button><button @click="(!dirty||confirm('丢弃未保存修改？'))&&load()">重新加载</button>
 </aside><main><div ref="mapEl" class="transit-map"></div><div class="map-tip">{{action==='route'?'按行车方向点击地图添加折线点':action==='stop'?'点击地图放置新站点':action==='move'?'点击地图移动所选站点':'选择线路或站点进行编辑'}}</div></main></div>
</section></Teleport></template>
<style scoped>.transit-workbench{position:fixed;inset:0;z-index:2300;background:#f1f5f9;display:flex;flex-direction:column;color:#172b4d;font:14px/1.5 var(--app-font)}.transit-workbench header{padding:14px 20px;background:white;display:flex;align-items:center;gap:14px;border-bottom:1px solid #ddd}.transit-workbench header span{flex:1}.layout{display:flex;flex:1;min-height:0}.layout aside{width:330px;flex-shrink:0;overflow:auto;padding:18px;background:white}.layout main{flex:1;position:relative;min-width:0}.transit-map{position:absolute;inset:0}.map-tip{position:absolute;bottom:24px;left:20px;z-index:800;padding:12px;background:white;border-radius:10px;box-shadow:0 2px 8px #0002}.transit-workbench label{display:block;margin:10px 0}.transit-workbench input:not([type=checkbox]),.transit-workbench select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.transit-workbench button{padding:8px 10px;border:1px solid #cbd5e1;background:white;border-radius:6px;margin:3px;cursor:pointer}.transit-workbench .active{background:#ede9fe;border-color:#8b5cf6}.transit-workbench p,.transit-workbench small{font-size:12px;color:#64748b;overflow-wrap:anywhere}.transit-workbench .error{color:#b91c1c}.vehicle{border-top:1px solid #ddd;padding:8px 0}.check{display:flex!important;gap:8px;align-items:center}.stop-order{font-size:12px}.stop-order button{padding:3px 8px}@media(max-width:750px){.layout{flex-direction:column-reverse}.layout aside{width:auto;max-height:48%}.layout main{min-height:30vh}.transit-workbench header{flex-wrap:wrap;padding:8px;gap:5px}}</style>
